INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 30, 'theory', 'Квиз: QEMU: потоки, цикл событий, virtio-blk');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 30, 0, 'Какой поток QEMU с ускорителем KVM выполняет ioctl(KVM_RUN) для виртуального процессора?', '["Главный поток, в котором работает главный цикл", "Отдельный поток на каждый vCPU, при debug-threads он называется «CPU n/KVM»", "Поток worker из пула блокирующих задач", "Ядро само, QEMU вызывает его один раз при старте"]', 1, 'В kvm_start_vcpu_thread для каждого vCPU создаётся поток, который крутит kvm_cpu_exec и в нём KVM_RUN. Главный поток занят главным циклом, worker выполняет блокирующие вызовы.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 30, 1, 'Что происходит с большим замком QEMU (BQL) в kvm_cpu_exec перед циклом KVM_RUN?', '["Он удерживается весь цикл, чтобы гость не менял память", "Он берётся заново перед каждым ioctl", "Он делится между vCPU поровну", "Он отпускается: гость работает без замка, а код устройства берёт его сам, если нужно"]', 3, 'kvm_cpu_exec вызывает bql_unlock до цикла; обработчики IO и MMIO вызываются вне замка, а память устройств берёт замок в prepare_mmio_access, если область не помечена lockless_io.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 30, 2, 'Зачем для очереди virtio-blk заводят ioeventfd на адрес уведомления?', '["Запись гостя по этому адресу только сигналит eventfd в ядре, без выхода в QEMU, и обработчик контекста просыпается по дескриптору", "Чтобы гость мог читать диск напрямую, минуя QEMU", "Чтобы QEMU мог отключить прерывания гостя", "Чтобы каждый запрос обрабатывался в главном цикле под BQL"]', 0, 'По документации KVM_IOEVENTFD запись по зарегистрированному адресу сигналит событие вместо выхода. Дескриптор отслеживает AioContext очереди — главный или iothread.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 30, 3, 'В каком порядке aio_poll (QEMU 10.2.0) выполняет работу после ожидания?', '["Таймеры, готовые fd, отложенные вызовы", "Готовые fd, таймеры, отложенные вызовы", "Завершения io_uring, отложенные вызовы (BH), готовые обработчики fd, таймеры", "Только таймеры; остальное делает главный поток"]', 2, 'В util/aio-posix.c после ожидания идут fdmon_ops->dispatch (завершения io_uring), aio_bh_poll, aio_dispatch_ready_handlers и timerlistgroup_run_timers — именно в таком порядке.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 30, 4, 'Как завершение запроса, обработанного в iothread, доходит до гостя?', '["iothread сам вызывает прерывание гостя, взяв BQL", "virtqueue_push пишет элемент в used ring, а virtio_notify сигналит уведомитель (eventfd), который при KVM с MSI-X привязан к irqfd", "Гость опрашивает used ring, QEMU ничего не сигналит", "Сигналом SIGUSR1 потоку vCPU"]', 1, 'Путь прерывания требует BQL, поэтому в virtio_irq для iothread выбран уведомитель гостя; KVM превращает его в прерывание через irqfd (KVM_IRQFD). Кольцо used пишется без BQL.');
